// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseTokenAddr,
        address nftAddr,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // Admissible domain: a pool initialized with distinct base token and NFT addresses,
        // any valid reserves/fees. Keep the domain wide so the fuzzer can pick any pair.
        vm.assume(baseTokenAddr != address(0));
        vm.assume(nftAddr != address(0));
        vm.assume(baseTokenAddr != nftAddr);

        c.initialize(
            baseTokenAddr,
            nftAddr,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // General rule: after initialize, the pool's base token is exactly the address
        // supplied as _baseToken (and hence distinct from the pool's nft when the inputs differ).
        assertTrue(c.baseToken() == baseTokenAddr);
    }
}
